"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[8397],{145:(e,n,i)=>{i.d(n,{A:()=>t});const t=i.p+"assets/images/figure3_edge_demo-a8815d92619a62e41dff4bccbe5679b9.png"},4716:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>h,frontMatter:()=>s,metadata:()=>t,toc:()=>d});const t=JSON.parse('{"id":"2026/drought-early-warning","title":"Multimodal Drought Early Warning at the Edge","description":"Authors: Di Fan (University of Florida), Levi Johnson (Colorado State University), John Blackwell (Colorado State University), and Atefeh Hosseini (University of Kansas)","source":"@site/science/2026/drought-early-warning.md","sourceDirName":"2026","slug":"/2026/drought-early-warning","permalink":"/science/2026/drought-early-warning","draft":false,"unlisted":false,"tags":[{"inline":true,"label":"Sage Summer Camp","permalink":"/science/tags/sage-summer-camp"},{"inline":true,"label":"Water & Hydrology","permalink":"/science/tags/water-hydrology"},{"inline":true,"label":"Multimodal Learning","permalink":"/science/tags/multimodal-learning"},{"inline":true,"label":"Edge AI","permalink":"/science/tags/edge-ai"}],"version":"current","sidebarPosition":5,"frontMatter":{"sidebar_position":5,"sidebar_label":"Drought Early Warning","keywords":["Sage Summer Camp","Drought","Multimodal","NEON"],"tags":["Sage Summer Camp","Water & Hydrology","Multimodal Learning","Edge AI"]},"sidebar":"tutorialSidebar","previous":{"title":"Dangerous Animal Detection","permalink":"/science/2026/dangerous-animal-detection"},"next":{"title":"Biotic Interaction","permalink":"/science/2026/bisonn"}}');var a=i(74848),r=i(28453);const s={sidebar_position:5,sidebar_label:"Drought Early Warning",keywords:["Sage Summer Camp","Drought","Multimodal","NEON"],tags:["Sage Summer Camp","Water & Hydrology","Multimodal Learning","Edge AI"]},o="Multimodal Drought Early Warning at the Edge",l={},d=[{value:"Introduction",id:"introduction",level:2},{value:"Motivation",id:"motivation",level:3},{value:"Our Work",id:"our-work",level:3},{value:"Data",id:"data",level:2},{value:"System Overview",id:"system-overview",level:2},{value:"Edge Demonstration",id:"edge-demonstration",level:2},{value:"Live Forecast",id:"live-forecast",level:3},{value:"Historical Replay",id:"historical-replay",level:3},{value:"Model Evidence",id:"model-evidence",level:3},{value:"Preliminary Findings",id:"preliminary-findings",level:2},{value:"Current Limitations",id:"current-limitations",level:2},{value:"Future Directions",id:"future-directions",level:2},{value:"Code and Resources",id:"code-and-resources",level:2},{value:"Acknowledgments",id:"acknowledgments",level:2}];function c(e){const n={a:"a",blockquote:"blockquote",h1:"h1",h2:"h2",h3:"h3",header:"header",img:"img",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"multimodal-drought-early-warning-at-the-edge",children:"Multimodal Drought Early Warning at the Edge"})}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Authors:"})," Di Fan (",(0,a.jsx)(n.a,{href:"https://ufl.edu",children:"University of Florida"}),"), Levi Johnson (",(0,a.jsx)(n.a,{href:"https://colostate.edu",children:"Colorado State University"}),"), John Blackwell (",(0,a.jsx)(n.a,{href:"https://colostate.edu",children:"Colorado State University"}),"), and Atefeh Hosseini (",(0,a.jsx)(n.a,{href:"https://ku.edu",children:"University of Kansas"}),")"]}),"\n",(0,a.jsx)(n.h2,{id:"introduction",children:"Introduction"}),"\n",(0,a.jsx)(n.h3,{id:"motivation",children:"Motivation"}),"\n",(0,a.jsx)(n.p,{children:"Drought affects water availability, ecosystem health, vegetation condition, agriculture, and wildfire risk. Regional drought products provide essential large-scale information, but local conditions can change between reporting cycles. Instrumented environmental sites offer a complementary view through frequent atmospheric, soil, and vegetation observations."}),"\n",(0,a.jsx)(n.p,{children:"Using these observations in near real time is not straightforward. Environmental measurements may arrive at different times, individual sensors may be temporarily unavailable, and a recent landscape image may not yet have been collected. An edge system must therefore be able to analyze the information that is currently available, communicate when evidence is incomplete, and update its assessment when new observations arrive."}),"\n",(0,a.jsx)(n.p,{children:"This project investigates multimodal drought early warning using the Sage edge-computing ecosystem. We use the National Ecological Observatory Network (NEON) Caddo\u2013Lyndon B. Johnson National Grasslands site (CLBJ) in north-central Texas as an initial pilot. CLBJ provides a useful combination of atmospheric, soil, and PhenoCam observations in a Southern Plains environment."}),"\n",(0,a.jsxs)(n.p,{children:["Texas is used here as a starting example rather than the final geographic scope. Future work will extend the study to sites in Colorado, Wyoming, and other climate regions to examine how well the approach transfers across different ecosystems and sensor configurations.\n",(0,a.jsx)(n.img,{alt:"Edge demonstration",src:i(95870).A+"",width:"2568",height:"1424"})]}),"\n",(0,a.jsxs)(n.blockquote,{children:["\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:"Figure 1 Motivation."})}),"\n"]}),"\n",(0,a.jsx)(n.h3,{id:"our-work",children:"Our Work"}),"\n",(0,a.jsx)(n.p,{children:"We developed a research prototype that combines environmental sensor histories with landscape imagery to estimate current drought conditions and provide short-term outlooks. The system is designed around a realistic operational constraint: all expected inputs may not be available at the same moment."}),"\n",(0,a.jsx)(n.p,{children:"Instead of requiring a complete synchronized record, the prototype tracks which observations are present, which are delayed, and how recently each source was updated. It can produce an initial result from partial information and revise the result after an additional sensor record or image becomes available."}),"\n",(0,a.jsx)(n.p,{children:"The system also provides a natural-language analysis interface. The numerical forecast is generated first and then passed to a vision-language model for explanation. This design keeps the scientific prediction separate from the user-facing narrative."}),"\n",(0,a.jsx)(n.p,{children:"The current prototype supports historical replay and analysis of newly supplied observations. It has also been migrated to an NVIDIA Thor development node to evaluate whether the workflow can operate in an edge-oriented environment. Automatic subscription to deployed Sage or NEON data streams remains future work."}),"\n",(0,a.jsx)(n.h2,{id:"data",children:"Data"}),"\n",(0,a.jsx)(n.p,{children:"The pilot study uses archived NEON observations from CLBJ covering approximately five years. The available measurements include precipitation, air temperature, relative humidity, atmospheric pressure, radiation, wind, soil moisture, soil temperature, soil carbon dioxide, and soil heat flux."}),"\n",(0,a.jsx)(n.p,{children:"Daily PhenoCam imagery provides a complementary view of vegetation appearance and landscape change. The image archive contains more than 1,700 usable frames. Sensor and image records are aligned through their timestamps while preserving the causal order of observations."}),"\n",(0,a.jsx)(n.p,{children:"Quality flags and missing records are retained during preprocessing. This is important because missingness is part of the deployment problem rather than only a data-cleaning issue. The model must distinguish between a measured normal value and a value that has not yet arrived."}),"\n",(0,a.jsx)(n.p,{children:"The current-condition component is anchored to a precipitation-based drought indicator calculated only from information available at the prediction time. Learned outputs provide short-term meteorological and soil-related outlooks. The exact target construction and evaluation protocol are reserved for the associated scientific manuscripts."}),"\n",(0,a.jsx)(n.h2,{id:"system-overview",children:"System Overview"}),"\n",(0,a.jsx)(n.p,{children:"The prototype contains three main components:"}),"\n",(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Environmental time-series analysis"}),", which summarizes recent atmospheric and soil observations."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Visual analysis"}),", which represents vegetation and landscape information from the most recent usable PhenoCam image."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Availability-aware multimodal inference"}),", which combines the evidence that is actually present at a given time."]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"A pretrained visual representation model is used to encode the PhenoCam imagery. A vision-language model provides structured visual interpretation and a user-facing explanation layer. Missing or delayed modalities are represented explicitly so that an unavailable image is not treated as a real image containing zero-valued features."}),"\n",(0,a.jsx)(n.p,{children:"The dashboard separates the observed current condition from learned future forecasts. It reports the current evidence, short-term risk estimates, input availability, and an overall reliability indicator. The language model is used to explain these outputs but does not independently redefine the numerical forecast."}),"\n",(0,a.jsx)(n.p,{children:"Further architectural details, feature construction, training objectives, and fusion strategies are intentionally omitted from this public project description and will be reported in future peer-reviewed work."}),"\n",(0,a.jsx)(n.h2,{id:"edge-demonstration",children:"Edge Demonstration"}),"\n",(0,a.jsx)(n.p,{children:"The demonstration provides three complementary views."}),"\n",(0,a.jsx)(n.h3,{id:"live-forecast",children:"Live Forecast"}),"\n",(0,a.jsxs)(n.p,{children:["The Live Forecast interface accepts currently available sensor measurements, a recent image, or either modality independently. This allows the system to demonstrate prediction under incomplete observations rather than requiring every input to arrive at once.\n",(0,a.jsx)(n.img,{alt:"Edge demonstration",src:i(33987).A+"",width:"2734",height:"1622"})]}),"\n",(0,a.jsxs)(n.blockquote,{children:["\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:"Figure 2 Live Forecast."})}),"\n"]}),"\n",(0,a.jsx)(n.h3,{id:"historical-replay",children:"Historical Replay"}),"\n",(0,a.jsx)(n.p,{children:"Historical Replay reconstructs a selected point in the archive and shows how the output changes as additional observations become available. It is intended to represent asynchronous environmental data collection rather than claim that the archive contains original real-time ingestion timestamps."}),"\n",(0,a.jsx)(n.h3,{id:"model-evidence",children:"Model Evidence"}),"\n",(0,a.jsx)(n.p,{children:"Model Evidence separates observation-based indicators from learned predictions and highlights cases in which the sources of evidence agree, disagree, or are insufficient. This distinction is important for avoiding an overly confident interpretation of a research prototype."}),"\n",(0,a.jsxs)(n.p,{children:["The numerical inference pipeline and dashboard currently run in a GPU-enabled container on an NVIDIA Thor development node. A locally hosted language model provides the explanatory interface. The scientific forecast remains available even when the language model is slow or unavailable.\n",(0,a.jsx)(n.img,{alt:"Edge demonstration",src:i(145).A+"",width:"1226",height:"816"})]}),"\n",(0,a.jsxs)(n.blockquote,{children:["\n",(0,a.jsx)(n.p,{children:(0,a.jsx)(n.strong,{children:"Figure 3 Edge demonstration."})}),"\n"]}),"\n",(0,a.jsx)(n.h2,{id:"preliminary-findings",children:"Preliminary Findings"}),"\n",(0,a.jsx)(n.p,{children:"Initial experiments suggest that the prototype can reproduce meaningful drought episodes within the CLBJ historical record and can continue operating when selected inputs are unavailable. The results also show that the value of imagery depends on the prediction target and the state of the sensor network."}),"\n",(0,a.jsx)(n.p,{children:"Environmental sensors remain particularly important for precipitation-defined meteorological drought. Imagery provides a different source of evidence related to visible vegetation response and may become more useful when sensor coverage is degraded or when the target concerns ecosystem or soil response."}),"\n",(0,a.jsx)(n.p,{children:"These findings motivate an availability-aware multimodal design, but they should not be interpreted as evidence of geographic generalization. Detailed numerical results, event-based evaluation, baselines, calibration analysis, and ablation studies are reserved for future scientific publications."}),"\n",(0,a.jsx)(n.h2,{id:"current-limitations",children:"Current Limitations"}),"\n",(0,a.jsx)(n.p,{children:"The current system is a single-site research prototype. Its evaluation demonstrates temporal performance at CLBJ but not transfer to other geographic regions."}),"\n",(0,a.jsx)(n.p,{children:"The historical archive also does not reproduce every aspect of an operational data stream. Arrival delays used in the replay are simulated, and newly supplied observations are entered manually. The Thor deployment demonstrates computational portability, but the device is not physically deployed at the CLBJ site."}),"\n",(0,a.jsx)(n.p,{children:"Sensor quality and coverage vary across measurements and time. The PhenoCam record also contains changes in imaging conditions that must be considered when interpreting visual trends. These issues are active research topics rather than fully solved components."}),"\n",(0,a.jsx)(n.p,{children:"The dashboard should therefore be viewed as a demonstration of a possible edge workflow, not as an operational drought advisory or a replacement for official drought products."}),"\n",(0,a.jsx)(n.h2,{id:"future-directions",children:"Future Directions"}),"\n",(0,a.jsx)(n.p,{children:"The next engineering step is integration with the Sage/Waggle software ecosystem. A native edge application could subscribe to available sensor and camera measurements, maintain a rolling causal state, run inference after meaningful updates, and publish results through the Sage data infrastructure."}),"\n",(0,a.jsx)(n.p,{children:"The next scientific step is multi-site evaluation. Planned additions include NEON sites in Colorado and Wyoming, followed by cross-site experiments that measure transfer across climate regions, vegetation types, sensor layouts, and camera views."}),"\n",(0,a.jsx)(n.p,{children:"Future research will also examine uncertainty calibration, event-level evaluation, adaptive model selection, and resource-aware execution. Lightweight numerical inference could run whenever new measurements arrive, while more expensive visual or language analysis could be triggered only by meaningful changes or explicit user requests."}),"\n",(0,a.jsx)(n.p,{children:"This direction connects local drought early warning with the broader Sage objective of responsive, distributed, and resource-aware artificial intelligence at the edge."}),"\n",(0,a.jsx)(n.h2,{id:"code-and-resources",children:"Code and Resources"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:(0,a.jsx)(n.a,{href:"https://sagecontinuum.org/science/2025/dynamic-data-collection",children:"Sage Project Example: Application-Agnostic Dynamic Data Collection for AI on the Edge"})}),"\n",(0,a.jsx)(n.li,{children:(0,a.jsx)(n.a,{href:"https://sagecontinuum.org/docs/tutorials/edge-apps/intro-to-edge-apps",children:"Sage Edge App Tutorials"})}),"\n",(0,a.jsx)(n.li,{children:(0,a.jsx)(n.a,{href:"https://sagecontinuum.org/docs/tutorials/access-waggle-sensors",children:"Sage Access Waggle Sensors Tutorial"})}),"\n",(0,a.jsx)(n.li,{children:(0,a.jsx)(n.a,{href:"https://github.com/waggle-sensor",children:"Waggle Sensor GitHub"})}),"\n",(0,a.jsx)(n.li,{children:(0,a.jsx)(n.a,{href:"https://www.neonscience.org/field-sites/clbj",children:"NEON CLBJ Field Site"})}),"\n",(0,a.jsx)(n.li,{children:"Project code repository: [Add repository URL]"}),"\n",(0,a.jsx)(n.li,{children:"Interactive demo: [Add stable demo URL]"}),"\n"]}),"\n",(0,a.jsx)(n.h2,{id:"acknowledgments",children:"Acknowledgments"}),"\n",(0,a.jsx)(n.p,{children:"This project uses data provided by the National Ecological Observatory Network and edge-computing resources provided through the Sage/Waggle ecosystem. Add team member names, mentors, institutional support, and funding acknowledgments before publication."})]})}function h(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},28453:(e,n,i)=>{i.d(n,{R:()=>s,x:()=>o});var t=i(96540);const a={},r=t.createContext(a);function s(e){const n=t.useContext(r);return t.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),t.createElement(r.Provider,{value:n},e.children)}},33987:(e,n,i)=>{i.d(n,{A:()=>t});const t=i.p+"assets/images/liveforecast-cb4d2fe221904dacd148ec10dad03f83.png"},95870:(e,n,i)=>{i.d(n,{A:()=>t});const t=i.p+"assets/images/figure1_motivation-ba44b3742aa9018b8a38ed20cf406b0b.png"}}]);